def fail(msg):
    print("FAIL: " + msg)
    sys.exit(1)


def build():
    out = []
    for n, L in enumerate(LESSONS, 1):
        # resolve the starting position
        if L.get("setup_san"):
            b = chess.Board()
            for san in L["setup_san"]:
                try:
                    b.push_san(san)
                except Exception as e:
                    fail(f"[{L['id']}] setup move {san}: {e}")
            fen = b.fen()
        else:
            fen = L["fen"]
            b = chess.Board(fen)
            if not b.is_valid():
                fail(f"[{L['id']}] invalid FEN: {fen} ({b.status()!r})")

        rec = dict(id=L["id"], title=L["title"], fen=fen, text=L["text"], ex=[],
                   part=L.get("part", "part-one"))
        if L.get("source"):
            rec["source"] = L["source"]
        if L.get("flip"):
            rec["flip"] = True

        for j, e in enumerate(L["ex"], 1):
            tag = f"[{L['id']} ex{j}]"
            q = dict(kind=e["kind"], prompt=e["prompt"], why=e["why"])

            # any exercise may play some moves out on the board before it asks its
            # question, so a question can be about a position further down the line
            board = chess.Board(fen)
            if e.get("setup_before"):
                pre = []
                for san in e["setup_before"]:
                    try:
                        mv = board.push_san(san)
                    except Exception as ex_:
                        fail(f"{tag} setup_before {san} illegal in {board.fen()}: {ex_}")
                    pre.append(mv.uci())
                q["pre"] = pre

            if e["kind"] == "choice":
                q["options"] = e["options"]
                q["ok"] = e["ok"]
                if not (0 <= e["ok"] < len(e["options"])):
                    fail(f"{tag} ok index out of range")

            elif e["kind"] in ("piece", "square"):
                for s in e["ok"]:
                    if chess.parse_square(s) is None:
                        fail(f"{tag} bad square {s}")
                if e["kind"] == "piece":
                    for s in e["ok"]:
                        if board.piece_at(chess.parse_square(s)) is None:
                            fail(f"{tag} no piece on {s}")
                q["ok"] = e["ok"]
                if e.get("pick"):
                    q["pick"] = e["pick"]
                    for s in e["pick"]:
                        if e["kind"] == "piece" and board.piece_at(chess.parse_square(s)) is None:
                            fail(f"{tag} pick square {s} is empty")
                    for s in e["ok"]:
                        if s not in e["pick"]:
                            fail(f"{tag} ok {s} missing from pick list")

            elif e["kind"] == "move":
                oks = []
                for san in e["ok_san"]:
                    probe = board.copy()
                    try:
                        mv = probe.push_san(san)
                    except Exception as ex_:
                        fail(f"{tag} ok move {san} illegal in {board.fen()}: {ex_}")
                    oks.append(mv.uci())
                q["ok"] = oks
                q["okSan"] = list(e["ok_san"])
                if e.get("then_san"):
                    line = board.copy()
                    line.push_san(e["ok_san"][0])
                    thens = []
                    for san in e["then_san"]:
                        try:
                            mv = line.push_san(san)
                        except Exception as ex_:
                            fail(f"{tag} then move {san} illegal in {line.fen()}: {ex_}")
                        thens.append(mv.uci())
                    q["then"] = thens
            else:
                fail(f"{tag} unknown kind {e['kind']}")

            rec["ex"].append(q)

        # The board must face the player who is being asked to move, otherwise you
        # are dragging your own pieces away from you. Checked here rather than left
        # to review, because it is invisible in the data and obvious on screen.
        for j, (q, e) in enumerate(zip(rec["ex"], L["ex"]), 1):
            if q["kind"] != "move":
                continue
            probe = chess.Board(fen)
            for u in q.get("pre", []):
                probe.push_uci(u)
            want_flip = not probe.turn                     # Black to move means flip
            if bool(L.get("flip")) != want_flip:
                side = "White" if probe.turn else "Black"
                fail(f"[{L['id']} ex{j}] board faces the wrong way: you play {side} "
                     f"but flip={bool(L.get('flip'))}")

        out.append(rec)
        print(f"ok  {n:>2}. {L['id']:<28} {len(rec['ex'])} exercises")
    return out


