# The page unlocks lessons by their position in the flat list but draws the parts
# in PART_META order, so those two orders have to agree. A part whose lessons are
# out of order, or split by another part's, would render above a part it actually
# unlocks after, and the padlocks would appear in the wrong card.
ids=[L["id"] for L in data]
if len(ids) != len(set(ids)):
    fail(f"duplicate lesson ids: {[i for i in set(ids) if ids.count(i)>1]}")

seen_order = []
for L in data:
    if not seen_order or seen_order[-1] != L["part"]:
        seen_order.append(L["part"])
if len(seen_order) != len(set(seen_order)):
    fail(f"a part's lessons are not contiguous in the list: {seen_order}")
if seen_order != [pid for pid, _, _ in PART_META]:
    fail(f"lesson order {seen_order} does not match PART_META order "
         f"{[pid for pid, _, _ in PART_META]}")

PARTS = []
for pid, title, blurb in PART_META:
    ids = [L["id"] for L in data if L["part"] == pid]
    if not ids:
        fail(f"part {pid} has no lessons")
    PARTS.append(dict(id=pid, title=title, blurb=blurb, lessons=ids))
orphans = {L["part"] for L in data} - {p["id"] for p in PARTS}
if orphans:
    fail(f"lessons reference unknown parts: {sorted(orphans)}")

OUT = "/home/parallels/website/tools/chess-assets/course-lessons.json"
doc = dict(v=1, parts=PARTS, lessons=data)
js = json.dumps(doc, indent=1, ensure_ascii=False)
open(OUT, "w", encoding="utf-8").write(js)
open("lessons.json", "w", encoding="utf-8").write(js)
print(f"\nwrote {OUT} ({len(js)} bytes, {len(data)} lessons in {len(PARTS)} part)")

# prose guard: the site style rules ban em dashes and contractions in page prose.
# Possessives (White's rook) are fine, so match a contraction wordlist rather than
# any apostrophe-s.
import re

CONTRACTIONS = re.compile(
    r"\b("
    r"it|that|there|here|what|who|let|he|she|one|everything|nothing|something"
    r")['’]s\b"
    r"|\w+n['’]t\b"
    r"|\b\w+['’](re|ll|ve|m|d)\b",
    re.I,
)
bad = []
for L in data:
    blobs = list(L["text"]) + [L["title"]]
    for e in L["ex"]:
        blobs += [e["prompt"], e["why"]] + list(e.get("options", []))
    for s in blobs:
        if "—" in s or "–" in s:
            bad.append(("em dash", s))
        m = CONTRACTIONS.search(s)
        if m:
            bad.append((f"contraction {m.group(0)!r}", s))
if bad:
    print("\nPROSE WARNINGS:")
    for kind, s in bad:
        print(f"  {kind}: {s[:110]}")
else:
    print("prose check clean (no em dashes, no contractions)")
